"""Capacity bounded Democratic Trust Propagation repair."""

from collections import Counter
from hashlib import sha256
from heapq import heappush, heappop
from math import gcd

from .agreement import best_band_from_counts, PPM

_digest = sha256


class RepairResult:
    """Frozen, immutable repair evidence."""

    __slots__ = ('links', 'order', 'values', 'confidences', 'counter_items',
                 'cell_confidence')

    def __init__(self, links, order, values, confidences, counter_items):
        self.links = links
        self.order = order
        self.values = values
        self.confidences = confidences
        self.counter_items = counter_items
        # Per counter cell: (corrected, numerator, denominator).
        cells = {}
        for key, value, num, den in counter_items:
            cells[key] = (value, num, den)
        self.cell_confidence = cells


def _trial_samples(seed, trials, router, flow, pool):
    """Reproducible scenario values for one (router, flow) pair."""
    width = len(pool)
    if width == 0:
        return [0] * trials
    if width == 1 or len(set(pool)) == 1:
        return [pool[0]] * trials
    prefix = '%d:%d:' % (seed, router)
    a, b = flow
    suffix = ':%d:%d' % (a, b)
    out = []
    append = out.append
    for t in range(trials):
        word = _digest((prefix + str(t) + suffix).encode('ascii')).digest()
        pick = int.from_bytes(word[:8], 'big') % width
        append(pool[pick])
    return out


def compute_repair(topology, trials, epsilon, seed, counters, predictions,
                   predicted):
    """Freeze a repair certificate for the current measured state.

    ``counters`` maps every valid counter key to an integer or ``None``.
    ``predictions`` maps flows to clamped predicted loads and is only consulted
    when ``predicted`` is true (nonnull routing plan).
    """
    flows = topology.flows
    cap = topology.cap
    sigma = topology.sigma
    incident = topology.incident
    endpoints = topology.endpoints
    flow_keys = topology.flow_keys
    span = PPM - epsilon

    # Ordered baseline pools.
    pools = {}
    base_counts = {}
    for flow in flows:
        pool = []
        for key in flow_keys[flow]:
            value = counters.get(key)
            if value is not None:
                pool.append(value)
        if predicted:
            pool.append(predictions[flow])
        pools[flow] = pool
        counts = {}
        for value in pool:
            counts[value] = counts.get(value, 0) + trials
        base_counts[flow] = counts

    # Reproducible scenario identities and router conservation imbalances.
    samples = {}
    delta = {}
    for router in topology.node_ids:
        for flow in incident[router]:
            samples[(router, flow)] = _trial_samples(seed, trials, router, flow,
                                                     pools[flow])
    for router in topology.node_ids:
        balance = [0] * trials
        for flow in incident[router]:
            word = samples[(router, flow)]
            if sigma[(router, flow)] > 0:
                for t in range(trials):
                    balance[t] -= word[t]
            else:
                for t in range(trials):
                    balance[t] += word[t]
        delta[router] = balance

    bands = {router: {} for router in topology.node_ids}

    # Initial evidence for every (router, incident unfixed flow) pair.
    for router in topology.node_ids:
        local = bands[router]
        balance = delta[router]
        for flow in incident[router]:
            word = samples[(router, flow)]
            limit = cap[flow]
            values = []
            append = values.append
            if sigma[(router, flow)] > 0:
                for base, sample in zip(balance, word):
                    value = base + sample
                    append(0 if value < 0 else (limit if value > limit else value))
            else:
                for base, sample in zip(balance, word):
                    value = sample - base
                    append(0 if value < 0 else (limit if value > limit else value))
            local[flow] = best_band_from_counts(Counter(values), span)

    def evidence(flow):
        counts = dict(base_counts[flow])
        for router in endpoints[flow]:
            value, mass = bands[router][flow]
            counts[value] = counts.get(value, 0) + mass
        return best_band_from_counts(counts, span)

    candidates = {}
    supports = {}
    generation = {flow: 0 for flow in flows}
    values = {}
    confidences = {}
    order = []
    heap = []
    dirty = set(flows)
    fixed_count = 0
    total = len(flows)
    while fixed_count < total:
        for flow in dirty:
            candidate, support = evidence(flow)
            candidates[flow] = candidate
            supports[flow] = support
            generation[flow] += 1
            heappush(heap, (-support, flow[0], flow[1], generation[flow]))
        dirty.clear()
        while True:
            _, a, b, stamp = heappop(heap)
            flow = (a, b)
            if flow in values:
                continue
            if generation[flow] != stamp:
                continue
            break
        value = candidates[flow]
        support = supports[flow]
        values[flow] = value
        step = gcd(support, trials)
        confidences[flow] = (support // step, trials // step)
        order.append(flow)
        fixed_count += 1
        if fixed_count == total:
            break
        for router in endpoints[flow]:
            balance = delta[router]
            word = samples[(router, flow)]
            sign = -sigma[(router, flow)]
            for t in range(trials):
                balance[t] += sign * (value - word[t])
            local = bands[router]
            for other in incident[router]:
                if other in values:
                    continue
                dirty.add(other)
                limit = cap[other]
                w2 = samples[(router, other)]
                out = []
                push = out.append
                if sigma[(router, other)] > 0:
                    for base, sample in zip(balance, w2):
                        cand = base + sample
                        push(0 if cand < 0 else (limit if cand > limit else cand))
                else:
                    for base, sample in zip(balance, w2):
                        cand = sample - base
                        push(0 if cand < 0 else (limit if cand > limit else cand))
                local[other] = best_band_from_counts(Counter(out), span)

    links = []
    counter_items = []
    for flow in flows:
        value = values[flow]
        num, den = confidences[flow]
        links.append((flow[0], flow[1], value, num, den))
        for key in flow_keys[flow]:
            counter_items.append((key, value, num, den))
    return RepairResult(tuple(links), tuple(order), values, confidences,
                        tuple(counter_items))
